<script setup lang="ts">
import { computed } from 'vue'
import type { ReturnHistoryEntry } from './接口契约'
import ReturnMoney from './金额资料.vue'
const props = defineProps<{ entry: ReturnHistoryEntry; contentOnHold?: boolean }>()
const value = computed(() => props.entry.parsedAttributes)
const hasData = computed(() => { const item = value.value; return !!item && (item.keepOriginalItem !== null || item.partialRefundAmount || item.refundDeductionType || item.rmaNumber || item.sellerReturnAddress || item.updatedTrackingNumber || item.moneyMovementRef || item.escalateReason || item.rlspType) })
</script>
<template><dl v-if="hasData && value" class="history-attributes"><template v-if="value.keepOriginalItem !== null"><dt>商品安排</dt><dd>{{ value.keepOriginalItem ? '买家保留商品，无需寄回' : '买家退回商品' }}</dd></template><template v-if="value.partialRefundAmount"><dt>部分退款报价</dt><dd><ReturnMoney :value="value.partialRefundAmount" /></dd></template><template v-if="value.refundDeductionType"><dt>退款扣减</dt><dd><ReturnMoney v-if="value.refundDeductionType.amount" :value="value.refundDeductionType.amount" /><span v-if="value.refundDeductionType.percentage !== null" class="deduction-percentage">比例 {{ value.refundDeductionType.percentage }}%</span></dd></template><template v-if="value.rmaNumber"><dt>退货授权编号</dt><dd>{{ value.rmaNumber }}</dd></template><template v-if="value.sellerReturnAddress"><dt>当时退回地址</dt><dd class="address-text">{{ contentOnHold ? '平台已隐藏历史地址内容' : [value.sellerReturnAddress.name, value.sellerReturnAddress.addressLine1, value.sellerReturnAddress.addressLine2, [value.sellerReturnAddress.city, value.sellerReturnAddress.stateOrProvince, value.sellerReturnAddress.postalCode].filter(Boolean).join(', '), value.sellerReturnAddress.country].filter(Boolean).join('\n') }}</dd></template><template v-if="value.updatedTrackingNumber"><dt>更新后跟踪号</dt><dd>{{ value.updatedTrackingNumber }}</dd></template><template v-if="value.moneyMovementRef"><dt>资金记录引用</dt><dd>{{ value.moneyMovementRef }}</dd></template><template v-if="value.escalateReason"><dt>介入原因原值</dt><dd>{{ value.escalateReason }}</dd></template><template v-if="value.rlspType"><dt>面单提供方原值</dt><dd>{{ value.rlspType }}</dd></template></dl></template>
<style scoped>.history-attributes{display:grid;grid-template-columns:92px minmax(0,1fr);gap:9px 8px;border-top:1px solid #e6ecf2;padding-top:12px;margin:12px 0 0;font-size:12px;line-height:1.8}.history-attributes dt{color:#909399}.history-attributes dd{margin:0;overflow-wrap:anywhere}.address-text{white-space:pre-line}.deduction-percentage{display:block}</style>
